def _bind(case: dict) -> tuple[dict, list]:
    ks = [{"name": f["name"], "definition": f["definition"], "formula": "", "unit": "", "period": "monthly", "owner": "x", "status": "defined"} for f in case["figs"]]
    R.bind(None, None, ks, case["goal"])
    names = {f["name"] for f in case["figs"]}
    return ({k["name"]: k["built_from"] for k in ks if k["name"] in names}, sorted(k["built_from"] for k in ks if k["name"] not in names))


def _q(ask: str) -> str | None:
    return (R.match({"name": ask}, strict=False) or {}).get("id")


# ---- every case that passed in run 4 keeps its question and its bindings ---------------------------------------------------------------------

PASSED_R4 = [uc for uc, c in CASES.items() if c["r4"]]


@pytest.mark.parametrize("uc", PASSED_R4)
def test_a_case_that_passed_in_run_4_keeps_its_question_and_its_bindings(uc):
    c = CASES[uc]
    assert _q(c["ask"]) == c["q"], (uc, c["ask"])
    want, added = _bind(c)
    assert want == c["want"], uc
    assert added == c["added"], uc


# ---- regressions: passed in run 4, failed in run 5 -------------------------------------------------------------------------------------------

def test_uc017_the_after_debt_figure_is_net_worth_after_debt_and_a_board_line_in_the_goal_does_not_add_the_board_pack():
    # the goal says "in one line I can take to the board": board and family were enough to add board_summary, whose answer replaced the after-debt figure
    c = CASES["uc-017-liab"]
    want, added = _bind(c)
    assert want["Net family worth after debt"] == "net_worth_after_debt" and _q(c["ask"]) == "net_worth_after_debt"
    assert "board_summary" not in added


def test_the_board_pack_is_still_asked_for_by_a_board_pack_and_by_what_to_tell_the_board():
    # uc-074: "Before the family board I need one page" and the question "What to tell the board of the family?"
    c = CASES["uc-074-boardpack"]
    assert _q(c["ask"]) == "board_summary" and "board_summary" in _bind(c)[1]
    assert _q("Give me the board pack headline figures") == "board_summary"
    assert not R.asks("At each month end I want what the family is worth after that debt, in one line I can take to the board.", R.recipe("board_summary"))


def test_uc021_stale_valuations_are_the_valuation_age_recipe():
    c = CASES["uc-021-stale"]
    assert _bind(c)[0] == {"Stale‑valuation share": "value_age_days"} and _q(c["ask"]) == "value_age_days"
    assert R.asks(c["goal"], R.recipe("value_age_days"))


def test_uc040_the_latest_call_fee_is_a_memo_figure():
    c = CASES["uc-040-icmemo"]
    want = _bind(c)[0]
    assert want["Latest call fee"] == "memo_support"
    assert want["Called amount (incl. latest call)"] == want["Unfunded commitments"] == "called_to_date"  # the call fee names change no other figure
    assert (R.match({"name": "Fee in latest call", "definition": "Management fee amount included in the most recent capital call"}) or {}).get("id") == "memo_support"
    assert (R.match({"name": "Call fee check"}) or {}).get("id") == "call_fee_check"  # the fee check keeps its own name


def test_uc044_the_quarter_return_and_the_benchmark_relative_return_are_the_return_recipe():
    c = CASES["uc-044-twr"]
    want = _bind(c)[0]
    assert want["Quarter‑to‑date return"] == want["Benchmark‑relative return"] == want["Year‑to‑date return"] == "time_weighted_return"
    assert _q(c["ask"]) == "time_weighted_return"


def test_uc046_the_allocation_or_selection_decision_is_the_attribution_and_a_goal_that_beat_the_benchmark_asks_for_it():
    c = CASES["uc-046-attrib"]
    assert _q(c["ask"]) == "attribution" and "attribution" in _bind(c)[1]
    assert _bind(c)[0]["Benchmark‑relative return"] == "time_weighted_return"


def test_uc3_the_chase_email_drafts_are_the_missing_statements_recipe_not_a_design_of_span():
    c = CASES["uc3-statements-inbox"]
    assert _bind(c)[0]["Chase‑email drafts prepared"] == "missing_statements"
    assert (R.match({"name": "Chase-email drafts prepared", "definition": "Number of draft emails created for missing statements"}) or {}).get("id") == "missing_statements"


