def test_the_names_added_for_run_5_do_not_take_the_questions_of_the_cases_around_them():
    for q, other in [("Is the Cedarpoint call fee right against the fund terms?", "call_fee_check"), ("Can we commit 2 million to the new fund?", "commit_check"),
                     ("What do we owe each of the family?", "allowance_due"), ("Which statements are missing?", "missing_statements"),
                     ("What is the net worth?", "net_worth"), ("What is the return for the year?", "time_weighted_return")]:
        assert _q(q) in (other, None), q
